<p><?=t('Выберите раздел в меню. Изменения опубликованных записей сразу отображаются на сайте.','Choose a section. Changes to published records immediately appear on the website.')?></p><div class="admin-tiles"><?php foreach(Content::sections() as $section=>$meta):if(!Auth::can($section))continue;?><a href="/admin/content/<?=$section?>"><span><?=count(Content::all($section))?></span><h2><?=h(t($meta['name'],$meta['en']))?></h2><p><?=t('Добавить, изменить, снять с публикации','Create, edit, unpublish')?> ↗</p></a><?php endforeach;?><?php if(Auth::can('orders')):?><a href="/admin/orders"><span><?=count(DB::all('SELECT id FROM orders'))?></span><h2><?=t('Заказы','Orders')?></h2><p><?=t('Состав, стоимость, статус и уведомления','Items, totals, status and notifications')?> ↗</p></a><?php endif;?></div>
